import { Icon, type IconDefinition } from '@finalytic/icons';
import {
  ActionIcon,
  type ActionIconProps,
  Indicator,
  Tooltip,
  useMantineTheme,
} from '@mantine/core';
import type { EmotionSx } from '@mantine/emotion';
import { type ComponentProps, type ReactNode, forwardRef } from 'react';

type Props = {
  count?: number;
  onClick: React.MouseEventHandler<HTMLButtonElement> | undefined;
  icon: IconDefinition;
  iconSize?: number;
  size?: ComponentProps<typeof ActionIcon<'button'>>['size'];
  strokeWidth?: number;
  color?: ComponentProps<typeof Icon>['color'];
  tooltip?: ReactNode;
  tooltipMaxWidth?: number;
  variant?: 'default' | 'outline';
  sx?: EmotionSx;
  id?: string;
} & Omit<
  ActionIconProps,
  'onClick' | 'children' | 'color' | 'size' | 'variant' | 'sx'
>;

export const IconButton = forwardRef<HTMLButtonElement, Props>(
  (
    {
      onClick,
      icon,
      variant = 'default',
      iconSize: is,
      size: buttonSize,
      color,
      count,
      tooltip,
      strokeWidth,
      sx,
      id,
      tooltipMaxWidth,
      ...props
    },
    ref
  ) => {
    'use memo';

    const theme = useMantineTheme();

    const defaultSize = variant === 'outline' ? 16 : 18;

    const size = is ?? defaultSize;

    return (
      <Tooltip
        label={tooltip}
        withArrow
        disabled={!tooltip || (typeof tooltip === 'string' && !tooltip?.trim())}
        maw={tooltipMaxWidth}
        multiline
      >
        <Indicator
          label={count}
          color={theme.colors.red[9]}
          position="top-end"
          styles={() => ({
            indicator: {
              height: 15,
              width: 16,
              fontSize: 11,
              borderRadius: '100%',
            },
          })}
          offset={0}
          disabled={!count}
        >
          <ActionIcon
            id={id}
            onClick={onClick}
            ref={ref}
            size={buttonSize}
            variant={variant === 'default' ? 'transparent' : 'outline'}
            sx={(theme, u) => ({
              borderRadius: theme.radius.md,
              borderColor:
                variant === 'outline' ? theme.colors.neutral[3] : undefined,
              borderWidth: variant === 'outline' ? 1 : undefined,
              borderStyle: variant === 'outline' ? 'solid' : undefined,
              padding: theme.spacing.xs,
              '&:hover': {
                backgroundColor: `${theme.colors.gray[0] + 30}!important`,
              },
              ...((typeof sx === 'function' ? sx(theme, u) : sx || {}) as any),
            })}
            {...props}
          >
            <Icon
              icon={icon}
              color={color}
              size={size}
              strokeWidth={strokeWidth}
            />
          </ActionIcon>
        </Indicator>
      </Tooltip>
    );
  }
);
