import { LoadingIndicator, type SelectItem } from '@finalytic/ui';
import { type ComponentProps, useMemo } from 'react';
import { Select, type SelectDataProps } from '../select';
import type { SelectValueProps } from '../select/_types';
import { FilterPill } from './FilterPill';
import { pluralize } from '@vrplatform/ui-common';

type Props<TSelectValue extends string> = {
  label: string;
  multiLabel?: string;
  popoverWidth?: number;
  popoverHeight?: number;
  withinPortal?: boolean;
  loadingMode?: 'indicator';
  searchPlaceholder?: string;
  hideClearButton?: boolean;
  hideSearch?: boolean;
  hideIcon?: boolean;
  noOptionsText?: string;
  pinnedItems?: SelectItem[];
  customBottomActions?: ComponentProps<typeof Select>['customBottomActions'];
  width?: number;
  filterType?: ComponentProps<typeof FilterPill>['type'];
} & SelectDataProps<TSelectValue> &
  SelectValueProps<TSelectValue>;

export const SelectFilter = <TSelectValue extends string>({
  setValue,
  value,
  label: filterLabel,
  withinPortal = true,
  multiLabel,
  popoverWidth = 250,
  // popoverHeight,
  loadingMode,
  searchPlaceholder,
  hideClearButton,
  hideSearch,
  hideIcon,
  noOptionsText,
  customBottomActions,
  width,
  filterType,
  ...dataProps
}: Props<TSelectValue>) => {
  const inputLoading = dataProps?.data?.loading;

  return (
    <Select
      {...dataProps}
      setValue={setValue as any}
      value={value as any}
      inputProps={{
        loadingQuery: inputLoading,
        width,
      }}
      dropdownProps={{
        position: 'bottom-start',
        preventCloseOnSelect: true,
        width: popoverWidth,
        // height: popoverHeight,
        withinPortal,
        searchPlaceholder,
        hideSearch,
        noOptionsText,
      }}
      customBottomActions={customBottomActions}
    >
      {({
        value: v,
        loadingQuery,
        opened,
        type,
        setValue,
        handlers,
        width,
      }) => {
        const label = useMemo(() => {
          if (type === 'multiple') {
            const value = v as SelectItem[] | null;

            let label = filterLabel;

            if (value?.length === 1) label = value[0].label;
            else if (value?.length)
              label = `${value.length} ${pluralize(value.length, multiLabel || filterLabel.toLowerCase())}`;

            return label;
          } else if (type === 'single') {
            const value = v as SelectItem | null;
            if (!value) return filterLabel;
            return value.label;
          }
        }, [v, filterLabel, type]);

        const isDefault = label === filterLabel;

        if (loadingQuery && loadingMode === 'indicator')
          return <LoadingIndicator size="xs" pt={2} />;

        return (
          <FilterPill
            opened={opened}
            isDefault={isDefault}
            type={filterType}
            icon={
              type === 'single' ? !hideIcon && (value as any)?.icon : undefined
            }
            label={label || ''}
            width={width}
            resetFilter={
              hideClearButton
                ? undefined
                : () => {
                    handlers.close();

                    type === 'single'
                      ? setValue(null, { type: 'removed', value: v! })
                      : setValue([], { type: 'removed', value: v[0] });
                  }
            }
          />
        );
      }}
    </Select>
  );
};
