import { useLocalStorage } from '@mantine/hooks';
import { type ReactNode, createContext, useContext, useMemo } from 'react';
import { useDashboard } from './dashboard';
import { useMe } from './team';

type C = {
  contactId: string | null;
  setContactId: (value: string | null) => void;
};

const ownerPortalContext = createContext<C>({
  contactId: null,
  setContactId: () => {},
});

export function useOwnerPortalContactIdLocalStorage() {
  const { id: meId } = useMe();

  const [contactId, setContactId] = useLocalStorage<string | null>({
    key: `${meId}_owp_cid`, // owp_cid = owner portal contact id
    defaultValue: null,
    getInitialValueInEffect: true,
  });

  return { contactId, setContactId };
}

export const OwnerPortalContactContextProvider = ({
  children,
}: {
  children: ReactNode;
}) => {
  const { ownerAccess = [] } = useMe();

  const { contactId, setContactId } = useOwnerPortalContactIdLocalStorage();

  const ownerPortalValue = useMemo<C>(() => {
    const first = ownerAccess[0];

    if (
      ownerAccess.length === 1 &&
      first &&
      (first.contactId || first.ownerId)
    ) {
      return {
        contactId: (first.contactId || first.ownerId)!,
        setContactId,
      };
    }

    const hasAccessToContact =
      contactId &&
      ownerAccess.some(
        (x) => x.contactId === contactId || x.ownerId === contactId
      );

    if (!hasAccessToContact || !ownerAccess.length) {
      return {
        contactId: null,
        setContactId,
      };
    }

    return {
      contactId,
      setContactId,
    };
  }, [contactId, setContactId, ownerAccess]);

  return (
    <ownerPortalContext.Provider value={ownerPortalValue}>
      {children}
    </ownerPortalContext.Provider>
  );
};

export const useOwnerPortalContact = () => {
  const context = useContext(ownerPortalContext);

  const [dashboard] = useDashboard();
  const isOwnerPortal = dashboard === 'owner';

  return useMemo<typeof context>(() => {
    return {
      ...context,
      contactId: isOwnerPortal ? context.contactId : null,
    };
  }, [context, isOwnerPortal]);
};
