import {
  CopyIcon,
  Icon,
  type IconDefinition,
  TrashIcon,
} from '@finalytic/icons';
import type { Maybe } from '@vrplatform/utils';
import {
  ActionIcon,
  Menu,
  type MenuItemProps,
  type MenuProps,
  Tooltip,
  useMantineTheme,
} from '@mantine/core';
import type { ReactNode } from 'react';
import { showSuccessNotification, useLegacyColors } from '../../../hooks';
import type { ExtendedCustomColors } from '../../../styles';
import { LoadingIndicator } from '../../loading-indicator';

type EllipsisMenuItemProps = Omit<MenuItemProps, 'icon'> & {
  icon?: IconDefinition;
  component?: any;
  to?: string;
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  disabled?: boolean;
  iconColor?: string;
  customIcon?: ReactNode;
  loading?: boolean;
  loadingColor?: ExtendedCustomColors;
  tooltip?: string;
};

export const EllipsisMenuDivider = Menu.Divider;

export const EllipsisMenuItem = ({
  children,
  icon,
  iconColor,
  customIcon,
  loading,
  loadingColor,
  tooltip,
  ...props
}: EllipsisMenuItemProps) => {
  const content = (
    <Menu.Item
      leftSection={
        loading ? (
          <LoadingIndicator color={loadingColor} size="xs" />
        ) : (
          customIcon ||
          (icon && <Icon icon={icon} color={iconColor} size={18} />)
        )
      }
      {...props}
    >
      {children}
    </Menu.Item>
  );

  return tooltip ? (
    <Tooltip label={tooltip} position="left" withArrow>
      {content}
    </Tooltip>
  ) : (
    content
  );
};

export const EllipsisMenuDangerItem = (props: EllipsisMenuItemProps) => {
  const { red } = useLegacyColors();

  return (
    <EllipsisMenuItem
      {...props}
      // icon={faTrashAlt}
      customIcon={
        <TrashIcon
          size={18}
          strokeWidth={1.5}
          color={props.iconColor || red.base}
        />
      }
      sx={{ color: red.base }}
      iconColor={props.iconColor || red.base}
      loadingColor="gray"
    />
  );
};

export const EllipsisMenuCopyItem = ({
  value,
  notification,
  ...props
}: EllipsisMenuItemProps & {
  value: Maybe<string>;
  notification?: string;
}) => {
  const theme = useMantineTheme();

  return (
    <EllipsisMenuItem
      customIcon={<CopyIcon size={16} color={theme.colors.neutral[5]} />}
      disabled={!value}
      onClick={() => {
        if (!value) return;

        navigator.clipboard.writeText(value).then(() =>
          showSuccessNotification({
            message: notification || 'ID was added to your clipboard.',
          })
        );
      }}
      {...props}
    >
      {props.children || 'Copy ID'}
    </EllipsisMenuItem>
  );
};

export const EllipsisMenuLabel = Menu.Label;

type Props = {
  children: ReactNode;
  icon?: IconDefinition;
  target?: ReactNode;
} & MenuProps;

export const EllipsisMenu = ({
  children,
  trigger = 'hover',
  icon,
  target,
  ...menuProps
}: Props) => {
  const { gray, themeColors: colors } = useLegacyColors();

  return (
    <Menu
      shadow="md"
      width={200}
      radius="md"
      position="bottom-end"
      withArrow
      withinPortal
      trigger={trigger}
      arrowOffset={10}
      styles={() => ({
        item: {
          height: 35,
        },
        label: {
          color: gray.dark,
          textTransform: 'uppercase',
        },
      })}
      {...menuProps}
    >
      <Menu.Target>
        {target || (
          <ActionIcon
            disabled={menuProps.disabled}
            variant="subtle"
            color="gray"
          >
            <Icon
              icon={icon || 'MoreHorizontalIcon'}
              size={18}
              color={colors.neutral[4]}
            />
          </ActionIcon>
        )}
      </Menu.Target>
      <Menu.Dropdown>{children}</Menu.Dropdown>
    </Menu>
  );
};
