const defaultHasuraUri = 'https://eu.hasura.vrplatform.app/v1/graphql';

export const GRAPHQL_URI = `${
  import.meta.env.VITE_GRAPHQL_URI || defaultHasuraUri
}`;

export const AUTH_REDIRECT_URL = import.meta.env.DEV
  ? 'https://tolocalhost.com/verification'
  : `https://${window.location.host}/verification`;

export const NEW_SIGN_IN = false;

type Platform = 'finalytic' | 'vrplatform';

export const PLATFORM: Platform =
  (import.meta.env.VITE_PLATFORM_NAME as Platform) || 'vrplatform';

// Google Maps api key

export const STATUS_PAGE =
  PLATFORM === 'finalytic'
    ? 'https://status.finalytic.io'
    : 'https://status.vrplatform.app';

export const isLocalhost =
  window.location.host.includes('localhost') ||
  window.location.host.includes('127.0.0.1');
export const isStaging =
  window.location.hostname === 'staging.portal.vrplatform.app';
export const isProduction =
  window.location.hostname === 'portal.vrplatform.app';
export const isExtension = window.location.href.startsWith('chrome-extension');
