import { useUser } from '@clerk/clerk-react';
import { parseAsString, useQueryState } from '@vrplatform/query-params';
import { type Maybe, day, isUUID, utc } from '@vrplatform/utils';
import { useLocalStorage } from '@mantine/hooks';
import type { HyperlineEntities } from '@vrplatform/hyperline-client';
import type { UserRole } from '@vrplatform/log';
import { VRP_TENANT_ID } from '@vrplatform/ui-common';
import {
  type ReactNode,
  createContext,
  useContext,
  useEffect,
  useMemo,
} from 'react';
import { useNavigate } from 'react-router';
import { isLocalhost } from '../env';
import { useQuery } from '../graphql';
import { useTrpcQuery } from '../trpc';
import { OwnerPortalContactContextProvider } from './owner';
import { useExtension } from './useExtension';
import { useIntercom } from './useIntercom';
import { useIsPlaywright } from './usePlaywright';
import { useTrackingIdentify } from './useTracking';

function _useLocalStorageTeamId(userId: string | undefined) {
  return useLocalStorage<string | undefined | null>({
    key: `${userId}_tid`,
    defaultValue: undefined,
  });
}

export type TeamType = 'partner' | 'propertyManager';

function __useMe(args: {
  userId?: string;
  realUserId?: string;
  activeTeamId?: string;
  role?: string;
  imageUrl?: string;
}) {
  const [sti, setSti] = useQueryState('sti', parseAsString);
  const [, setTeamId] = _useLocalStorageTeamId(args.userId);
  const { sendMessage } = useExtension();

  const identify = useTrackingIdentify();
  const intercom = useIntercom();

  const { isLoading: loadingSti, data: stiData } = useQuery(
    (q, args) => {
      if (!args.sti || !isUUID(args.sti)) return null;

      return q
        .tenant({
          where: {
            id: {
              _eq: args.sti,
            },
          },
          limit: 1,
        })
        .map((t) => ({
          id: t.id,
        }))[0];
    },
    {
      skip: !sti,
      variables: {
        sti,
      },
    }
  );

  const {
    data: userData,
    isLoading: loadingUser,
    error: errorUser,
    refetch: refetchUser,
  } = useQuery(
    (q, { userId, VRP_TENANT_ID, isOwner }) => {
      if (!userId)
        return {
          user: null,
        };

      const user =
        q
          .user({
            where: {
              id: { _eq: userId },
            },
            limit: 1,
          })
          .map((user) => {
            const partnerMemberships = user
              ?.memberships({
                where: {
                  _or: [
                    {
                      tenant: {
                        // Partner admin
                        type: { _eq: 'partner' },
                      },
                      role: { _eq: 'admin' },
                      status: { _eq: 'active' },
                    },
                    {
                      // VRP admin
                      tenantId: { _eq: VRP_TENANT_ID },
                      status: { _eq: 'active' },
                    },
                  ],
                },
              })
              .map((membership) => ({
                status: membership?.status,
                id: membership?.tenantId,
                role: membership?.role,
                teamType: membership?.tenant?.type,
              }));

            const isSuperAdmin = user.isAdmin;

            const hasPartnerMembership = partnerMemberships.some(
              (x) => x.id === VRP_TENANT_ID
            );

            const hasPartnerAdminMembership =
              partnerMemberships.find((x) => x.teamType === 'partner')?.role ===
              'admin';

            const isVrpAdmin = isSuperAdmin || hasPartnerMembership;

            const isPartnerAdmin =
              isSuperAdmin || isVrpAdmin || hasPartnerAdminMembership;

            return {
              id: user.id!,
              type: user.type!,
              name: user.name!,
              firstName: user.firstName,
              lastName: user.lastName,
              partnerId: user.partnerId,
              ownerAccess: isOwner
                ? user.ownerAccesses().map((x) => ({
                    contactId: x.contactId,
                    ownerId: x.ownerId,
                    role: x.role || 'viewer',
                  }))
                : [],
              isSuperAdmin,
              isPartnerAdmin,
              isVrpAdmin,
              email: user.email!,
              createdAt: user.createdAt!,
              featureApprovals: user.featureApprovals().map((approval) => ({
                id: approval.id,
                status: approval.status,
                featureId: approval.featureId,
              })),
            };
          })[0] || null;

      return {
        user,
      };
    },
    {
      skip: !args.userId,
      keepPreviousData: true,
      variables: {
        userId: args.userId,
        VRP_TENANT_ID,
        isOwner: args.role === 'owner',
      },
      queryKey: ['users', 'featureApprovals'],
    }
  );

  const {
    data: teamData,
    isLoading: loadingTeam,
    error: errorTeam,
    refetch: refetchTeam,
    isFetching: isFetchingTeam,
    queryKey: teamQueryKey,
  } = useQuery(
    (q, { userId, activeTeamId }) => {
      if (!userId)
        return {
          team: null,
        };

      const team =
        q
          .tenant({
            limit: 1,
            where: activeTeamId ? { id: { _eq: activeTeamId } } : undefined,
          })
          .map((item) => {
            const membership = item
              .members({ where: { userId: { _eq: userId } } })
              .map((x) => ({ id: x.id, role: x.role, status: x.status }))[0];

            const finalyticConnectionId = item
              .connections({
                where: {
                  appId: { _eq: 'finalytic' },
                },
                limit: 1,
                order_by: [{ appId: 'asc_nulls_first' }],
              })
              .map((connection) => connection.id)[0] as string;

            return {
              role: membership?.role as 'admin' | 'owner' | 'user',
              membershipId: membership?.id,
              membershipStatus: membership?.status,
              id: item.id!,
              statementStartAt:
                item.statementStartAt && utc(item.statementStartAt).isValid()
                  ? utc(item.statementStartAt).yyyymmdd()
                  : null,
              logo: item.logo!,
              name: item.name!,
              isGL: item.isGeneralLedger ?? false,
              currency: item.defaultCurrency,
              subscription: {
                cancelledAt: (item.cancelledAt
                  ? utc(item.cancelledAt).yyyymmdd()
                  : null) as string | null,
                trialUntil: (item.trialUntil
                  ? utc(item.trialUntil).yyyymmdd()
                  : null) as string | null,
                status:
                  item.billingSubscriptionStatus as HyperlineEntities['Subscription']['status'],
                paymentMethodType: (item.billingPaymentMethodType || null) as
                  | NonNullable<HyperlineEntities['PaymentMethod']>['type']
                  | null,
                customerId: item.billingCustomerId,
                plan: item.billingPlan,
              },
              status: item.status! as 'active' | 'inactive',
              isOnboarding: !!item.isOnboarding,
              createdAt: item.createdAt!,
              colorPrimary: item.colorPrimary!,
              booksClosedAt: item.booksClosedAt
                ? utc(item.booksClosedAt).yyyymmdd()
                : null,
              partnerId: item.partnerId!,
              billingPartnerId: item.calculatedBillingPartnerId,
              partnerName: item.partner?.name,
              enabledFeatures: item.enabledFeatures()?.map((x) => ({
                featureId: x.featureId,
                status: x.status,
                updatedAt: x.updatedAt,
              })),
              forceTwoFactorAuth: !!item
                .settings({
                  where: {
                    key: { _eq: 'tenantSettings' },
                    target: { _eq: 'forceTwoFactorAuth' },
                  },
                  limit: 1,
                })
                ?.map((x) => x.id)[0],
              type: item.type as TeamType,
              finalyticConnectionId,
            };
          })[0] ?? null;

      return {
        team,
      };
    },
    {
      skip: !args.userId,
      variables: {
        userId: args.userId,
        activeTeamId: stiData?.id || args.activeTeamId,
      },
      keepPreviousData: true,
      queryKey: ['teams', 'featureApprovals'],
    }
  );

  const user = userData?.user;
  const team = teamData?.team;

  const { data, isInitialLoading: loadingIntercomHash } = useTrpcQuery(
    'fetchIntercomHash',
    {
      tenantId: team?.id!,
    },
    {
      skip: !team?.id || !user?.id,
      refetchOnWindowFocus: false,
    }
  );

  const isTeamAdmin = useMemo(
    () =>
      user?.isSuperAdmin ||
      user?.isVrpAdmin ||
      user?.isPartnerAdmin ||
      team?.role === 'admin',
    [user?.isSuperAdmin, user?.isVrpAdmin, user?.isPartnerAdmin, team?.role]
  );

  const canAccessTeam = useMemo(
    () =>
      isTeamAdmin ||
      user?.isPartnerAdmin ||
      user?.isVrpAdmin ||
      user?.isSuperAdmin ||
      !!team?.membershipId,
    [
      isTeamAdmin,
      user?.isPartnerAdmin,
      user?.isVrpAdmin,
      user?.isSuperAdmin,
      team?.membershipId,
    ]
  );

  const intercomIdentifyId = data?.intercom_user_hash;

  const isPlaywright = useIsPlaywright(user?.email || '');

  const enableIdentify =
    !loadingIntercomHash &&
    !loadingUser &&
    !loadingTeam &&
    !loadingSti &&
    !!teamData &&
    !!userData?.user;

  useEffect(() => {
    if (isPlaywright || isLocalhost) {
      intercom.hardShutdown(); // prevent showing intercom completely
      return;
    }

    if (!enableIdentify || !user?.id || !intercomIdentifyId) return;

    identify({
      intercomIdentifyId,
      user: {
        id: user.id,
        email: user.email,
        avatar: args.imageUrl,
        lastSeenAt: day().toISOString(),
        name: user.name,
        firstName: user.firstName,
        lastName: user.lastName,
        createdAt: day(user.createdAt).toISOString(),
        isPartnerAdmin: user.isPartnerAdmin,
        isVrpAdmin: user.isVrpAdmin,
        isSuperAdmin: user.isSuperAdmin,
        isTeamAdmin,
        country: undefined, // TODO: add country?
        role: (user.isSuperAdmin
          ? 'super-admin'
          : user.isVrpAdmin
            ? 'vrp-admin'
            : user.isPartnerAdmin
              ? 'partner-admin'
              : isTeamAdmin
                ? 'team-admin'
                : team?.role ||
                  args.role || // this is the clerk role // (admin, user, owner)
                  'user') as UserRole,
      },
      team: team
        ? {
            id: team.id,
            name: team.name,
            isOnboarding: team.isOnboarding,
            isGL: team.isGL,
            type: team.type,
          }
        : undefined,
    });
  }, [
    enableIdentify,
    user,
    team,
    identify,
    isTeamAdmin,
    intercomIdentifyId,
    isPlaywright,
    args.imageUrl,
    args.role,
    intercom.hardShutdown,
  ]);

  useEffect(() => {
    if (stiData?.id && team?.id) {
      if (stiData.id === team.id) {
        setSti(null);
        setTeamId(stiData.id);
        sendMessage({ message: 'team_changed', data: { teamId: stiData.id } });
      }
    }
  }, [stiData, team?.id, setSti, setTeamId, sendMessage]);

  return {
    user: user
      ? { ...user, realUserId: args.realUserId, canAccessTeam, isTeamAdmin }
      : undefined,
    team,
    loading: loadingUser || loadingSti || loadingTeam,
    error: errorUser || errorTeam,
    isFetchingTeam,
    teamQueryKey,
    refetch: async () => {
      await Promise.allSettled([refetchUser(), refetchTeam()]);
    },
  };
}

type User = NonNullable<ReturnType<typeof __useMe>['user']>;
type Team = NonNullable<ReturnType<typeof __useMe>['team']>;

export const userContext = createContext<User>(undefined as any);

export const teamIdContext = createContext<{
  teamId: string;
  setTeamId: (value: string | null) => void;
}>({
  teamId: '',
  setTeamId: () => undefined,
});
export const teamContext = createContext<{
  teamId: string;
  setTeamId: (value: string) => void;
  team: Team;
  role: 'admin' | 'owner' | 'user';
  isTeamAdmin: boolean;
  isPartnerAdmin: boolean;
  isVrpAdmin: boolean;
  isSuperAdmin: boolean;
  isFetchingTeam: boolean;
  refetchTeam: () => Promise<void>;
  queryKey: readonly unknown[];
}>({
  isTeamAdmin: false,
  isPartnerAdmin: false,
  isVrpAdmin: false,
  isSuperAdmin: false,
  role: 'user',
  team: {} as any,
  teamId: '',
  isFetchingTeam: false,
  setTeamId: () => undefined,
  refetchTeam: async () => undefined,
  queryKey: [],
});

export function DBUserProvider({ children }: { children: ReactNode }) {
  const { user: u } = useUser();

  // const { ownerPreview } = useOwnerPreviewId();
  const realUserId = `${u?.publicMetadata.user_id || ''}`;
  // const ownerPreviewUserId = ownerPreview?.userId?.trim() || '';
  // const ownerPreviewTeamId = ownerPreview?.teamId?.trim() || '';

  const userId = `${u?.publicMetadata.user_id || ''}` || undefined;
  const [_teamId, setTeamId] = _useLocalStorageTeamId(userId);

  const { user, refetch, team, isFetchingTeam, teamQueryKey } = __useMe({
    userId,
    activeTeamId: _teamId ?? undefined,
    role: (u?.publicMetadata.role as Maybe<'user' | 'owner' | 'admin'>)
      ? `${u?.publicMetadata.role}`
      : undefined,
    realUserId,
    imageUrl: u?.imageUrl,
  });

  // For webextension
  useEffect(() => {
    if (u?.id) localStorage.setItem('cid', u.id);
    else localStorage.removeItem('cid');
    if (userId) localStorage.setItem('uid', userId);
    else localStorage.removeItem('uid');

    const tid = _teamId || team?.id;
    if (tid) localStorage.setItem('tid', tid);
    else localStorage.removeItem('tid');
  }, [userId, u?.id, _teamId, team?.id]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: <explanation>
  const teamIdValue = useMemo(() => {
    return {
      teamId: (_teamId || team?.id)!,
      setTeamId,
    };
  }, [_teamId || team?.id, setTeamId]);

  const teamValue = useMemo(() => {
    return {
      teamId: team?.id!,
      setTeamId,
      team: team! || {},
      role: team?.role as any,
      isSuperAdmin: user?.isSuperAdmin ?? false,
      isVrpAdmin: user?.isVrpAdmin ?? false,
      isPartnerAdmin: user?.isPartnerAdmin ?? false,
      isTeamAdmin: user?.isTeamAdmin ?? false,
      refetchTeam: refetch,
      isFetchingTeam,
      queryKey: teamQueryKey,
    };
  }, [
    team,
    setTeamId,
    refetch,
    user?.isSuperAdmin,
    user?.isVrpAdmin,
    user?.isPartnerAdmin,
    user?.isTeamAdmin,
    isFetchingTeam,
    teamQueryKey,
  ]);

  return (
    <userContext.Provider value={user!}>
      <teamIdContext.Provider value={teamIdValue}>
        <teamContext.Provider value={teamValue}>
          <OwnerPortalContactContextProvider>
            {children}
          </OwnerPortalContactContextProvider>
        </teamContext.Provider>
      </teamIdContext.Provider>
    </userContext.Provider>
  );
}

export function useMe() {
  let user = useContext(userContext);
  if (!user) user = {} as any;
  return user;
}

export function useTeamId() {
  const { sendMessage } = useExtension();
  const goto = useNavigate();

  let tenant = useContext(teamIdContext);
  if (!tenant) tenant = [undefined, () => undefined] as any;

  // biome-ignore lint/suspicious/useAwait: <explanation>
  const setTeamId = async (teamId: string | null, path?: string) => {
    tenant.setTeamId(teamId);

    const isLinkSharing = window.location.search?.includes('sti=');

    if (!isLinkSharing && !path) {
      if (window.location.pathname.startsWith('/reports/statement-summaries')) {
        goto('/reports/statement-summaries');
      } else if (window.location.pathname.includes('statement')) {
        goto('/statements');
      } else if (window.location.pathname.startsWith('/reconciliation')) {
        goto('/reconciliation');
      } else if (window.location.pathname.startsWith('/deposit')) {
        goto('/deposits');
      } else if (window.location.pathname.startsWith('/expense')) {
        goto('/expenses');
      } else if (window.location.pathname.startsWith('/listing')) {
        goto('/listings');
      } else if (window.location.pathname.startsWith('/contact')) {
        goto('/contacts');
      } else if (window.location.pathname.startsWith('/connection')) {
        goto('/connections');
      } else if (window.location.pathname.startsWith('/fees-commission')) {
        goto('/fees-commissions');
      } else if (window.location.pathname.startsWith('/dashboard')) {
        goto('/');
      }
    }

    if (path) {
      goto(path);
    }

    try {
      sendMessage({ message: 'team_changed', data: { teamId } });
    } catch (error) {
      console.log(error);
    }
  };

  return [tenant.teamId, setTeamId] as [
    string,
    (value: string | null, path?: string) => void,
  ];
}

export function useTeam() {
  const tenant = useContext(teamContext);

  return useMemo(
    () =>
      [
        tenant.team,
        tenant.refetchTeam,
        tenant.isFetchingTeam,
        tenant.queryKey,
      ] as const,
    [tenant.team, tenant.refetchTeam, tenant.isFetchingTeam, tenant.queryKey]
  );
}

export function useTeamRole() {
  const tenant = useContext(teamContext);

  return {
    teamRole: tenant.role,
    isTeamAdmin: tenant.isTeamAdmin,
    isPartnerAdmin: tenant.isPartnerAdmin,
    isSuperAdmin: tenant.isSuperAdmin,
    isVrpAdmin: tenant.isVrpAdmin,
  };
}
