import {
  showErrorNotification,
  showWarnNotification,
  updateErrorNotification,
} from '@finalytic/ui';
import type { Maybe } from '@vrplatform/utils';
import {
  keepPreviousData,
  useQuery as useTanstackQuery,
} from '@tanstack/react-query';
import type { ApiClientError, paths } from '@vrplatform/api';
import type { HasuraClient } from '@vrplatform/graphql';
import createFetchClient, { type Middleware } from 'openapi-fetch';
import createClient from 'openapi-react-query';
import { createContext, useContext, useMemo } from 'react';
import { PLATFORM } from '../env';
import { type QueryKey, useGqtyClient } from '../graphql';
import { captureSentryError, useTeamId } from '../hooks';
import { useNetwork } from '@mantine/hooks';

const isStagingApi =
  window.location.hostname === 'localhost' ||
  window.location.hostname === 'staging.portal.vrplatform.app' ||
  window.location.hostname.includes('app-256.pages.dev');

const apiHost =
  (typeof localStorage !== 'undefined'
    ? localStorage.getItem('api-endpoint')?.replaceAll('"', '')
    : undefined) || `${isStagingApi ? 'staging.' : ''}api.vrplatform.app`;
const protocol = apiHost.includes('localhost') ? 'http' : 'https';
const BASE_URL = apiHost.startsWith('http')
  ? apiHost
  : `${protocol}://${apiHost}`;

export type api = paths;

export { ApiClientError } from '@vrplatform/api';

const context = createContext<Client>({
  queryOptions: undefined,
  useMutation: undefined,
  useQuery: undefined,
  useSuspenseQuery: undefined,
} as any);

type Client = ReturnType<typeof createClient<paths>> & {
  $api: ReturnType<typeof createFetchClient<paths>>;
};

export const getApiErrorMessage = (
  error: ApiClientError,
  defaultMessage: string
) => error?.issues?.[0]?.message || error?.message || defaultMessage;

export const showApiErrorNotification = ({
  error,
  title,
  defaultMessage = 'Please try again later and contact support if the issue persists.',
  id,
}: {
  error: any;
  title: string;
  defaultMessage?: string;
  id?: string;
}) => {
  const message = getApiErrorMessage(error, defaultMessage);

  if (id) {
    updateErrorNotification({
      id,
      title,
      message,
    });
  } else {
    showErrorNotification({
      title,
      message,
    });
  }
};

export const ApiClientProvider = ({
  children,
  getToken,
  teamId,
}: {
  children: React.ReactNode;
  getToken: () => Promise<Maybe<string>>;
  teamId: string;
}) => {
  const { $api, fetchClient } = useMemo(() => {
    const authMiddleware: Middleware = {
      async onRequest({ request }) {
        // const accessToken = await auth.session?.getToken({
        //   template: 'Hasura',
        // });

        const accessToken = await getToken();

        if (!accessToken) {
          throw new Error('No API access');
        }

        const existingHeaderTenantId = request.headers.get('x-team-id');
        const headerTenantId = existingHeaderTenantId || teamId;

        // add Authorization header to every request
        request.headers.set('Authorization', `Bearer ${accessToken}`);
        if (headerTenantId) request.headers.set('x-team-id', headerTenantId);
        request.headers.set(
          'x-transaction-id',
          Math.random().toString(36).substring(2, 9)
        );
        request.headers.set('platform', PLATFORM);

        return request;
      },
    };

    const fetchClient = createFetchClient<paths>({
      baseUrl: BASE_URL,
    });

    fetchClient.use(authMiddleware);

    const $api = createClient(fetchClient);
    return { $api, fetchClient };
  }, [teamId, getToken]);

  return (
    <context.Provider value={{ ...$api, $api: fetchClient }}>
      {children}
    </context.Provider>
  );
};
export const useApiMutation: Client['useMutation'] = (...props) =>
  useContext(context).useMutation(...props);

export const useApiClient = () => useContext(context).$api;

export type ApiClient = ReturnType<typeof useApiClient>;

class ApiQueryError extends Error {
  constructor(readonly message: string) {
    super(message);
    this.name = 'ApiQueryError';
  }
}

function handleQueryError(
  error: ApiClientError,
  opts: {
    hideNotification: boolean;
    title?: string;
  },
  extra: Record<string, string | boolean | undefined>
) {
  const title = opts.title || 'Query Error';
  const message = error?.message;

  if (!message) return;

  const lower = message.toLowerCase();

  const disableNotification =
    lower.includes('failed to fetch') ||
    lower.includes('load failed') ||
    lower.includes('database query error') ||
    lower.includes('no api access');

  const disableSentry = lower.includes('load failed');

  if (!disableSentry)
    captureSentryError(new ApiQueryError(message), {
      level: 'error',
      fingerprint: ['{{ default }}', 'api-query', message],
      extra: {
        ...extra,
        apiError: error,
      },
    });

  if (opts.hideNotification || disableNotification) {
    // do not show notification to user
    return;
  }

  if (lower.includes('exceeded the time limit of 60s')) {
    showWarnNotification({
      title: 'Connection Timeout',
      message: `Due to a possible slow internet connection, or temporarily high load on our servers, the connection from your computer has timed out. Please try again later.`,
    });
    return;
  }

  showApiErrorNotification({
    error,
    title: title,
    defaultMessage:
      'We failed to fetch your data. Please try again later and contact support if the issue persists. ',
  });
}

export function useApiQuery<TData, TArgs extends Record<string, unknown>>(
  fn: (
    api: ApiClient,
    variables: TArgs,
    hasura: HasuraClient['query']
  ) => Promise<TData>,
  options: {
    skip?: boolean;
    variables: TArgs;
    uniqueQueryKey: string;
    queryKeys?: QueryKey[];
    keepPreviousData?: boolean;
    errorTitle?: string;
    hideNotification?: boolean;
  }
) {
  const { online: isOnline } = useNetwork();

  const $api = useApiClient();
  const $graphql = useGqtyClient();

  const [teamId] = useTeamId();

  return useTanstackQuery({
    queryKey: [
      options.uniqueQueryKey,
      options.variables,
      ...(options.queryKeys || []),
      teamId,
      options.hideNotification,
    ],
    placeholderData: options.keepPreviousData ? keepPreviousData : undefined,
    staleTime: options?.keepPreviousData ? 30_000 : undefined,
    refetchOnWindowFocus: false,
    enabled: !options.skip,
    queryFn: () =>
      fn($api, options.variables, $graphql.query).catch(
        (error: ApiClientError) => {
          handleQueryError(
            error,
            {
              hideNotification: !!options.hideNotification,
              title: options.errorTitle,
            },
            {
              isOnline,
              query: fn?.toString(),
            }
          );
          throw error;
        }
      ),
  });
}
