import { RefreshCwIcon, SlidersHorizIcon } from '@finalytic/icons';
import {
  EllipsisMenu,
  EllipsisMenuDivider,
  EllipsisMenuItem,
  IconButton,
} from '@finalytic/ui';
import { ensure } from '@vrplatform/utils';
import {
  NativeSelect as MNativeSelect,
  Stack,
  rem,
  useMantineTheme,
} from '@mantine/core';
import type {
  MRT_ColumnDef,
  MRT_DensityState,
  MRT_TableInstance,
} from 'mantine-react-table';
import type { TableBasicRow, TableSortOptions } from './LazyTable.types';
import { type TableKey, useSavedTableSettings } from './useSavedTableSettings';

export const LazyTableSetting: <TRow extends TableBasicRow>(props: {
  table: MRT_TableInstance<TRow>;
  columnDefs: MRT_ColumnDef<TRow>[];
  tableKey: TableKey | undefined;
  canGroup: boolean;
  resetFilter?: () => void;
  sortOptions?: TableSortOptions;
}) => React.ReactNode = (props) => {
  const { colors } = useMantineTheme();

  const tableState = props.table.getState();
  const { resetTableSettings, setTableSettings } = useSavedTableSettings();

  const columns = props.columnDefs;
  const sortableColumns = columns.filter((c) => c.enableSorting);
  const groupableColumns = columns.filter((c) => c.enableGrouping);

  // const isFullScreen = tableState.isFullScreen;
  const density = tableState.density;
  const groupBy = tableState.grouping[0];
  const sortedBy = tableState.sorting[0]?.id;
  const dir = tableState.sorting[0]?.desc ? 'desc' : 'asc';

  const canSort = sortableColumns.length > 1 || !!props.sortOptions?.length;
  const sortOptions =
    props.sortOptions ||
    sortableColumns.map((column) => ({
      label: column.header,
      value: column.id || column.accessorKey || column.header,
    }));

  // const toggleFullScreen = () => {
  //   const isFullScreen = props.table.getState().isFullScreen;
  //   props.table.setIsFullScreen(!isFullScreen);
  // };

  const resetSettings = () => {
    if (props.tableKey) resetTableSettings(props.tableKey);
    props.table.reset();
    props.table.resetGrouping();
    props.table.resetSorting();
  };

  return (
    <EllipsisMenu
      closeOnItemClick={false}
      width={250}
      target={
        <IconButton>
          <SlidersHorizIcon color={colors.neutral[5]} size={20} />
        </IconButton>
      }
    >
      <Stack mx={10} py={5} gap={10}>
        {canSort && (
          <>
            <NativeSelect
              label="Sort by"
              value={sortedBy}
              onChange={(value) =>
                props.table.setSorting([
                  { id: value as string, desc: dir === 'desc' },
                ])
              }
              data={sortOptions}
            />
            <NativeSelect
              label="Sorting"
              value={dir}
              onChange={(value) =>
                props.table.setSorting([
                  { id: sortedBy, desc: value === 'desc' },
                ])
              }
              data={[
                {
                  label: 'Ascending',
                  value: 'asc',
                },
                {
                  label: 'Descending',
                  value: 'desc',
                },
              ]}
            />
          </>
        )}
        {props.canGroup && (
          <NativeSelect
            label="Group by"
            value={groupBy}
            onChange={(value) => {
              if (value === '-') {
                props.table.setGrouping([]);
                if (props.tableKey) {
                  setTableSettings(props.tableKey, {
                    groupBy: [],
                  });
                }
              } else {
                props.table.setGrouping([value]);
                if (props.tableKey) {
                  setTableSettings(props.tableKey, {
                    groupBy: [value],
                  });
                }
              }
            }}
            data={[
              { value: '-', label: '-' },
              ...groupableColumns.map((column) => ({
                label: column.header,
                value: column.id || column.accessorKey || column.header,
              })),
            ]}
          />
        )}
        <NativeSelect
          value={density}
          label="Density"
          onChange={(value) =>
            props.table.setDensity(value as MRT_DensityState)
          }
          data={ensure<{ label: string; value: MRT_DensityState }[]>([
            {
              label: 'Compact',
              value: 'xs',
            },
            {
              label: 'Normal',
              value: 'md',
            },
            {
              label: 'Wide',
              value: 'xl',
            },
          ])}
        />
      </Stack>

      {/* <EllipsisMenuDivider />

      <EllipsisMenuItem
        onClick={toggleFullScreen}
        customIcon={
          isFullScreen ? (
            <MinimizeIcon size={16} color={colors.neutral[5]} />
          ) : (
            <Maximize3Icon size={16} color={colors.neutral[5]} />
          )
        }
      >
        Toggle full screen
      </EllipsisMenuItem> */}

      <EllipsisMenuDivider />

      {/* {props.resetFilter && (
        <EllipsisMenuItem
          onClick={props.resetFilter}
          customIcon={<CrossIcon size={16} color={colors.neutral[5]} />}
        >
          Reset filtering
        </EllipsisMenuItem>
      )} */}

      <EllipsisMenuItem
        onClick={resetSettings}
        customIcon={<RefreshCwIcon size={16} color={colors.neutral[5]} />}
      >
        Reset settings
      </EllipsisMenuItem>

      {/* <EllipsisMenuDivider /> */}

      {/* TODO: Did not work! -- see https://linear.app/vrplatform/issue/PRO-10513/columns-filter-in-table-settings-did-no-work */}
      {/* <EllipsisMenuLabel
        sx={{
          textTransform: 'none',
          fontWeight: 400,
        }}
      >
        Columns
      </EllipsisMenuLabel>

      <Group gap={5} px={5} mb={5}>
        {columns.map((column) => (
          <ColumnVisibleToggle
            column={column}
            key={column.id || column.accessorKey || column.header}
            table={props.table}
            tableKey={props.tableKey}
          />
        ))}
      </Group> */}
    </EllipsisMenu>
  );
};

