const NativeSelect = ({
  data,
  onChange,
  value,
  label,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  data: TableSortOptions;
}) => (
  <MNativeSelect
    value={value}
    label={label}
    size="xs"
    styles={(theme) => ({
      root: {
        display: 'flex',
        flexWrap: 'nowrap',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: rem(10),
      },
      label: {
        flexShrink: 0,
        fontWeight: 400,
      },
      wrapper: {
        width: '100%',
        maxWidth: 140,
      },
      input: {
        borderColor: `${theme.colors.neutral[2]}`,
      },
    })}
    data={data}
    onChange={(e) => onChange(e.currentTarget.value)}
  />
);
