import type {
  accountClassification_enum,
  activeStatus_enum,
  party_enum,
} from '@vrplatform/graphql';
import {
  useQueryState as useQueryStateNuqs,
  useQueryStates as useQueryStatesNuqs,
  parseAsString,
  type HistoryOptions,
  parseAsBoolean,
  parseAsInteger,
  parseAsArrayOf,
  parseAsIsoDate,
  type UseQueryStatesKeysMap,
  parseAsStringLiteral,
} from 'nuqs';

import { NuqsAdapter } from 'nuqs/adapters/react-router/v6';

type UseQueryStateArgs<T> = Parameters<typeof useQueryStateNuqs<T>>;
type UseQueryStatesArgs<TKeyMap extends UseQueryStatesKeysMap> = Parameters<
  typeof useQueryStatesNuqs<TKeyMap>
>;

function useQueryState<T>(
  key: UseQueryStateArgs<T>[0],
  options: UseQueryStateArgs<T>[1]
) {
  return useQueryStateNuqs(key, {
    ...options,
    history: options.history || 'push',
  });
}
function useQueryStates<TKeyMap extends UseQueryStatesKeysMap>(
  ...args: UseQueryStatesArgs<TKeyMap>
) {
  return useQueryStatesNuqs(args[0], {
    ...args[1],
    history: args[1]?.history || 'push',
  });
}

// Classification
const CLASSIFICATIONS = Object.keys({
  asset: 'Asset',
  liability: 'Liability',
  revenue: 'Revenue',
  expense: 'Expense',
} satisfies Record<
  accountClassification_enum,
  string
>) as accountClassification_enum[];
const parseAsClassification = parseAsStringLiteral(CLASSIFICATIONS);

// Status
const ACTIVE_STATUSES: activeStatus_enum[] = ['active', 'inactive'];
const parseAsActiveStatus = parseAsStringLiteral(ACTIVE_STATUSES);

// Party
const PARTIES: party_enum[] = ['owners', 'manager'];
const parseAsParty = parseAsStringLiteral(PARTIES);

export {
  NuqsAdapter,
  useQueryState,
  useQueryStates,
  type HistoryOptions,
  parseAsString,
  parseAsBoolean,
  parseAsInteger,
  parseAsArrayOf,
  parseAsIsoDate,
  parseAsStringLiteral,
  parseAsClassification,
  parseAsActiveStatus,
  parseAsParty,
};
