import { Icon, type IconDefinition } from '@finalytic/icons';
import { Badge, type MantineSize } from '@mantine/core';
import { type ComponentProps, type PropsWithChildren, forwardRef } from 'react';

type Props = {
  shadow?: MantineSize;
  radius?: string | number;
  color?: string;
  leftIcon?: IconDefinition;
  leftIconSize?: number;
  backgroundColor?: string;
  withBorder?: boolean;
  leftIconColor?: ComponentProps<typeof Icon>['color'];
  component?: 'div' | 'button';
  size?: MantineSize;
  fontSize?: number;
  onClick?: (
    event: React.MouseEvent<HTMLDivElement | HTMLButtonElement>
  ) => void;
};

export const Tag = forwardRef<
  HTMLDivElement | HTMLButtonElement,
  PropsWithChildren<Props>
>(
  (
    {
      children,
      shadow,
      radius = 5,
      color,
      leftIcon,
      leftIconSize = 12,
      leftIconColor,
      backgroundColor = '#fff',
      withBorder = true,
      component,
      onClick,
      fontSize = 12,
      size = 'md',
      ...props
    },
    ref
  ) => (
    <Badge
      ref={ref as any}
      variant="default"
      size={size}
      component={component}
      onClick={onClick}
      sx={(theme) => ({
        color,
        borderColor: withBorder ? theme.colors.neutral[2] : 'transparent',
        height: '1.5rem',
        boxShadow: shadow ? theme.shadows[shadow] : undefined,
        borderRadius: radius,
        fontWeight: 400,
        textTransform: 'none',
        paddingInline: '7px',
        lineHeight: '1rem',
        backgroundColor,
        fontSize,
        cursor: onClick ? 'pointer' : undefined,
        ':active': onClick
          ? {
              transform: 'translateY(1px)',
            }
          : undefined,
      })}
      leftSection={
        leftIcon ? (
          <Icon icon={leftIcon} size={leftIconSize} color={leftIconColor} />
        ) : undefined
      }
      {...props}
    >
      {children}
    </Badge>
  )
);
